export const ShootAction: MessageFns<ShootAction> = {
  encode(message: ShootAction, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.ShootAt !== undefined) {
      Coordinate.encode(message.ShootAt, writer.uint32(10).fork()).join();
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): ShootAction {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const previousRecursionDepth = (reader as any).__tsProtoDecodeDepth ?? 0;
    if (previousRecursionDepth >= 100) {
      throw new globalThis.Error("protobuf decode recursion limit exceeded");
    }
    (reader as any).__tsProtoDecodeDepth = previousRecursionDepth + 1;
    try {
      const end = length === undefined ? reader.len : reader.pos + length;
      const message = createBaseShootAction();
      while (reader.pos < end) {
        const tag = reader.uint32();
        switch (tag >>> 3) {
          case 1: {
            if (tag !== 10) {
              break;
            }

            message.ShootAt = Coordinate.decode(reader, reader.uint32());
            continue;
          }
        }
        if ((tag & 7) === 4 || tag === 0) {
          break;
        }
        reader.skip(tag & 7);
      }
      return message;
    } finally {
      (reader as any).__tsProtoDecodeDepth = previousRecursionDepth;
    }
  },

  fromJSON(object: any): ShootAction {
    return { ShootAt: isSet(object.ShootAt) ? Coordinate.fromJSON(object.ShootAt) : undefined };
  },

  toJSON(message: ShootAction): unknown {
    const obj: any = {};
    if (message.ShootAt !== undefined) {
      obj.ShootAt = Coordinate.toJSON(message.ShootAt);
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<ShootAction>, I>>(base?: I): ShootAction {
    return ShootAction.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<ShootAction>, I>>(object: I): ShootAction {
    const message = createBaseShootAction();
    message.ShootAt = (object.ShootAt !== undefined && object.ShootAt !== null)
      ? Coordinate.fromPartial(object.ShootAt)
      : undefined;
    return message;
  },
};

function createBaseShotRecord(): ShotRecord {
  return { Coordinate: undefined, Result: 0 };
}

export const ShotRecord: MessageFns<ShotRecord> = {
  encode(message: ShotRecord, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.Coordinate !== undefined) {
      Coordinate.encode(message.Coordinate, writer.uint32(10).fork()).join();
    }
    if (message.Result !== 0) {
      writer.uint32(16).int32(message.Result);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): ShotRecord {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const previousRecursionDepth = (reader as any).__tsProtoDecodeDepth ?? 0;
    if (previousRecursionDepth >= 100) {
      throw new globalThis.Error("protobuf decode recursion limit exceeded");
    }
    (reader as any).__tsProtoDecodeDepth = previousRecursionDepth + 1;
    try {
      const end = length === undefined ? reader.len : reader.pos + length;
      const message = createBaseShotRecord();
      while (reader.pos < end) {
        const tag = reader.uint32();
        switch (tag >>> 3) {
          case 1: {
            if (tag !== 10) {
              break;
            }

            message.Coordinate = Coordinate.decode(reader, reader.uint32());
            continue;
          }
          case 2: {
            if (tag !== 16) {
              break;
            }

            message.Result = reader.int32() as any;
            continue;
          }
        }
        if ((tag & 7) === 4 || tag === 0) {
          break;
        }
        reader.skip(tag & 7);
      }
      return message;
    } finally {
      (reader as any).__tsProtoDecodeDepth = previousRecursionDepth;
    }
  },

  fromJSON(object: any): ShotRecord {
    return {
      Coordinate: isSet(object.Coordinate) ? Coordinate.fromJSON(object.Coordinate) : undefined,
      Result: isSet(object.Result) ? shotResultFromJSON(object.Result) : 0,
    };
  },

  toJSON(message: ShotRecord): unknown {
    const obj: any = {};
    if (message.Coordinate !== undefined) {
      obj.Coordinate = Coordinate.toJSON(message.Coordinate);
    }
    if (message.Result !== 0) {
      obj.Result = shotResultToJSON(message.Result);
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<ShotRecord>, I>>(base?: I): ShotRecord {
    return ShotRecord.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<ShotRecord>, I>>(object: I): ShotRecord {
    const message = createBaseShotRecord();
    message.Coordinate = (object.Coordinate !== undefined && object.Coordinate !== null)
      ? Coordinate.fromPartial(object.Coordinate)
      : undefined;
    message.Result = object.Result ?? 0;
    return message;
  },
};

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

export type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
